import sys

d = sys.stdin.read().split()
n, k = int(d[0]), int(d[1])
a = [int(x) for x in d[2:2 + n]]
m = n - k + 1
best = -1
for mask in range(1 << m):
    b = a[:]
    cnt = 0
    for j in range(m):
        if mask >> j & 1:
            cnt += 1
            for t in range(j, j + k):
                b[t] ^= 1
    if all(b):
        if best == -1 or cnt < best:
            best = cnt
print(best)

